def _enable_rls() -> None:
    # The app role: table privileges only. It never owns tables and has no BYPASSRLS.
    # On hosted Postgres it may already exist; on Docker db/init creates it first.
    op.execute(
        """
        DO $$
        BEGIN
          IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'trim_app') THEN
            CREATE ROLE trim_app NOLOGIN NOBYPASSRLS;
          END IF;
        END
        $$
        """
    )
    op.execute("GRANT USAGE ON SCHEMA public TO trim_app")

    # The user id set by app.db.user_session, or NULL when no user is set.
    op.execute(
        """
        CREATE FUNCTION app_current_user_id() RETURNS uuid
        LANGUAGE sql STABLE
        AS $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$
        """
    )
    op.execute("GRANT EXECUTE ON FUNCTION app_current_user_id() TO trim_app")

    for table, owner_col in RLS_TABLES.items():
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY {table}_owner ON {table} "
            f"USING ({owner_col} = app_current_user_id()) "
            f"WITH CHECK ({owner_col} = app_current_user_id())"
        )
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {table} TO trim_app")


def _create_auth_lookups() -> None:
    """The only reads allowed before a user is known. SECURITY DEFINER runs them as the owner,
    so each returns just the columns its flow needs, for one exact key."""
    op.execute(
        """
        CREATE FUNCTION auth_user_by_email(p_email text)
        RETURNS TABLE (id uuid, password_hash text, status text, email_verified_at timestamptz)
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
        AS $$
          SELECT u.id, u.password_hash, u.status, u.email_verified_at
          FROM users u
          WHERE u.email = lower(p_email) AND u.deleted_at IS NULL
        $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION auth_session_by_token(p_token_hash bytea)
        RETURNS TABLE (session_id uuid, user_id uuid, expires_at timestamptz)
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
        AS $$
          SELECT s.id, s.user_id, s.expires_at
          FROM sessions s
          WHERE s.token_hash = p_token_hash AND s.deleted_at IS NULL
        $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION auth_token_by_hash(p_token_hash bytea, p_kind text)
        RETURNS TABLE (token_id uuid, user_id uuid, expires_at timestamptz, used_at timestamptz)
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
        AS $$
          SELECT t.id, t.user_id, t.expires_at, t.used_at
          FROM auth_tokens t
          WHERE t.token_hash = p_token_hash AND t.kind = p_kind AND t.deleted_at IS NULL
        $$
        """
    )
    for fn in AUTH_LOOKUPS:
        op.execute(f"REVOKE ALL ON FUNCTION {fn} FROM PUBLIC")
        op.execute(f"GRANT EXECUTE ON FUNCTION {fn} TO trim_app")


